pub fn case_052_should_update_ocr1a_when_setting_tcnt_to_0_issue_111() -> Case {
    Case {
        source: r#"src/peripherals/timer.spec.ts"#,
        name: r#"timer / 16 bit timers / should update OCR1A when setting TCNT to 0 (issue #111)"#,
        line: 1269,
        assertions: 4,
        setup: setup_0(),
        body: vec![
            at(
                1270,
                destructure(
                    vec![
                        (r#"program"#, r#"program"#),
                        (r#"instructionCount"#, r#"instructionCount"#),
                    ],
                    call(
                        var(r#"asmProgram"#),
                        vec![text(
                            r#"
        CLR r1          ; r1 is our zero register
        LDI r16, 0x0    ; OCR1AH = 0x0;
        STS 0x89, r1    
        LDI r16, 0x8    ; OCR1AL = 0x8;
        STS 0x88, r16  
        ; Set waveform generation mode (WGM) to PWM Phase/Frequency Correct mode (9)
        LDI r16, 0x01   ; TCCR1A = (1 << WGM10);
        STS 0x80, r16  
        LDI r16, 0x11   ; TCCR1B = (1 << WGM13) | (1 << CS00);
        STS 0x81, r16  
        STS 0x85, r1    ; TCNT1H = 0x0;
        STS 0x84, r1    ; TCNT1L = 0x0;
        
        LDI r16, 0x5   ; OCR1AL = 0x5; // TCNT1 should read 0x0
        STS 0x88, r16  ; // TCNT1 should read 0x2 (going up)
        STS 0x84, r1   ; TCNT1L = 0x0;
        LDS r17, 0x84  ; // TCNT1 should read 0x1 (going up)
        LDS r18, 0x84  ; // TCNT1 should read 0x3 (going up)
        LDS r19, 0x84  ; // TCNT1 should read 0x5 (going down)
        LDS r20, 0x84  ; // TCNT1 should read 0x3 (going down)
      "#,
                        )],
                    ),
                ),
            ),
            at(1293, bind(r#"cpu"#, new(r#"CPU"#, vec![var(r#"program"#)]))),
            at(
                1294,
                eval(new(
                    r#"AVRTimer"#,
                    vec![var(r#"cpu"#), var(r#"timer1Config"#)],
                )),
            ),
            at(
                1296,
                bind(
                    r#"runner"#,
                    new(r#"TestProgramRunner"#, vec![var(r#"cpu"#)]),
                ),
            ),
            at(
                1297,
                eval(call(
                    get(var(r#"runner"#), text(r#"runInstructions"#)),
                    vec![var(r#"instructionCount"#)],
                )),
            ),
            at(
                1299,
                check(
                    call(get(var(r#"cpu"#), text(r#"readData"#)), vec![var(r#"R17"#)]),
                    r#"toEqual"#,
                    false,
                    vec![num(1.0)],
                ),
            ),
            at(
                1300,
                check(
                    call(get(var(r#"cpu"#), text(r#"readData"#)), vec![var(r#"R18"#)]),
                    r#"toEqual"#,
                    false,
                    vec![num(3.0)],
                ),
            ),
            at(
                1301,
                check(
                    call(get(var(r#"cpu"#), text(r#"readData"#)), vec![var(r#"R19"#)]),
                    r#"toEqual"#,
                    false,
                    vec![num(5.0)],
                ),
            ),
            at(
                1302,
                check(
                    call(get(var(r#"cpu"#), text(r#"readData"#)), vec![var(r#"R20"#)]),
                    r#"toEqual"#,
                    false,
                    vec![num(3.0)],
                ),
            ),
        ],
    }
}
#[test]
fn case_052_should_update_ocr1a_when_setting_tcnt_to_0_issue_111_native() {
    crate::run_native(case_052_should_update_ocr1a_when_setting_tcnt_to_0_issue_111());
}

